  "claims": [
    {
      "id": "c:3815476183",
      "kind": "approach",
      "harm": "parallelization could degrade rescan performance on non-SSD disks due to random I/O seeking",
      "quote": "Have you benchmarked this on a non-SSD?",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:3816289052"
      ],
      "fix_pushed": false,
      "settled_by_id": "c:4282211529",
      "settled_by_quote": "I have measured it on an Intel(R) Core(TM) i7-7700 CPU with 8 cores, 64Gi RAM and a HDD"
    },
    {
      "id": "rc:2778932090",
      "kind": "approach",
      "harm": "scanning thread competing for mutexes and tasks could starve workers and slow down rescanning",
      "quote": "All workers already process submit task in its own WorkThread just randomly trying to acquire mutex from scanning thread is non sense to me.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:2779171041",
        "rc:2786847431",
        "rc:3079604567"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3079604567",
      "settled_by_quote": "I have changed the implementation so that the main thread only joins task processing when it needs to clear the work queue"
    },
    {
      "id": "r:3787364700",
      "kind": "maintenance",
      "harm": "mixing scanning restructuring with parallelization overcomplicates review and combines distinct responsibilities",
      "quote": "I think it would be nice to first improve the current scanning code structure, then land the parallelization feature.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:3967677390"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:3967677390",
      "settled_by_quote": "I moved the test change into https://github.com/bitcoin/bitcoin/pull/34667 and the ScanForWalletTransactions refactor into https://github.com/bitcoin/bitcoin/pull/34681."
    },
    {
      "id": "rc:2940686723",
      "kind": "correctness",
      "harm": "sharing a global threadpool across wallets could let a rescan controller thread process tasks from another wallet's RPC, distorting latency",
      "quote": "Can't it happen that this controller thread picks up the task of another RPC of another wallet, thereby distorting results (from a RPC latency point of view) of this one?",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:2952982030",
        "rc:3079577515"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3079577515",
      "settled_by_quote": "I have moved away from a shared ThreadPool to one that is initialized before scanning and discarded after."
    }
  ],
